const fs = require('fs');

function main() {
  const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
  let ptr = 0;
  const N = +data[ptr++];
  const M = +data[ptr++];
  const T = new Int32Array(M);
  for (let i = 0; i < M; i++) T[i] = +data[ptr++];

  // 1) Calcula o tamanho da lista turno a turno.
  //    Um turno com t > L (tamanho atual) não remove ninguem e pode ser ignorado.
  let L = N;
  const eff = [];
  for (let i = 0; i < M; i++) {
    const t = T[i];
    if (t <= L) {
      eff.push(t);
      L -= Math.floor(L / t);
    }
  }

  // 2) Numero de convidados a listar: min(total de sobreviventes, 10000).
  //    A posicao final p (1-based) corresponde ao p-esimo convidado (menores numeros).
  const K = Math.min(L, 10000);
  const m = eff.length;

  // 3) Inversao: desfazemos os turnos do ultimo para o primeiro.
  //    No turno com t, a posicao p (sobrevivente) vai para p - floor(p/t).
  //    O inverso e': dado a nova posicao v, a antiga era
  //        g(v) = v + floor((v-1)/(t-1))
  //    (o v-esimo inteiro positivo nao multiplo de t), que e monotonia estrita.
  //    Assim, os K primeiros convidados sao obtidos aplicando g de todos os
  //    turnos, em ordem reversa, as posicoes finais 1..K.
  const res = new Int32Array(K);
  for (let i = 0; i < K; i++) res[i] = i + 1;

  for (let k = m - 1; k >= 0; k--) {
    const d = eff[k] - 1;
    if (res[K - 1] <= d) continue; // nenhum dos K primeiros valores e afetado
    if (d === 1) {
      // t = 2: g(v) = 2v - 1
      for (let i = 0; i < K; i++) {
        const v = res[i];
        res[i] = v + v - 1;
      }
    } else {
      for (let i = 0; i < K; i++) {
        const v = res[i];
        res[i] = v + (((v - 1) / d) | 0);
      }
    }
  }

  if (K > 0) process.stdout.write(res.join('\n') + '\n');
}

main();
